{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Retain newest-128 observed histories, clip cumulative position IDs at 32, and blend each state with its causal mean to represent stable interests. The generated predictor imports this same updated model class.",
      "edits": [
        {
          "find": "        pos = observed.cumsum(dim=1) * observed",
          "replace": "        pos = observed.cumsum(dim=1).clamp(max=32) * observed"
        },
        {
          "find": "        positions = torch.arange(maxlen, device=seq.device)\n        distance = positions[:, None] - positions[None, :]\n        weights = torch.exp(-distance.clamp_min(0).to(states.dtype) / 4.0)\n        weights = weights.masked_fill(distance < 0, 0.0)\n        pooled_sum = torch.matmul(weights, states)\n        pooled_mass = torch.matmul(weights, valid.to(states.dtype).unsqueeze(-1))\n        pooled = pooled_sum / pooled_mass.clamp_min(1e-8)\n        readout = 0.75 * states + 0.25 * pooled",
          "replace": "        pooled_sum = states.cumsum(dim=1)\n        pooled_mass = valid.to(states.dtype).cumsum(dim=1).unsqueeze(-1)\n        pooled = pooled_sum / pooled_mass.clamp_min(1.0)\n        readout = 0.8 * states + 0.2 * pooled"
        }
      ]
    },
    {
      "category": "learning_objective",
      "rationale": "Combine 80% pairwise BPR with 20% pointwise logistic supervision on the same sampled pairs, retaining valid-target weighting and optimizer settings.",
      "edits": [
        {
          "find": "            loss = F.softplus(-(pos_scores - neg_scores))\n            loss = (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "            pairwise_loss = F.softplus(-(pos_scores - neg_scores))\n            pointwise_loss = 0.5 * (F.softplus(-pos_scores) + F.softplus(neg_scores))\n            loss = 0.8 * pairwise_loss + 0.2 * pointwise_loss\n            loss = (loss * mask).sum() / mask.sum().clamp(min=1.0)"
        }
      ]
    },
    {
      "category": "feature_construction",
      "rationale": "Add a jointly learned input projection of standardized log training-item counts alongside existing frequency scaling. Persist feature values and normalization statistics in each category checkpoint, and require the generated predictor to restore them.",
      "edits": [
        {
          "find": "        self.input_frequency_scale[0] = 0.0\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)",
          "replace": "        self.input_frequency_scale[0] = 0.0\n        self.register_buffer(\"input_log_frequency\", torch.zeros(itemnum + 1))\n        self.register_buffer(\"log_frequency_mean\", torch.tensor(0.0))\n        self.register_buffer(\"log_frequency_std\", torch.tensor(1.0))\n        self.frequency_projection = nn.Linear(1, hidden_units, bias=False)\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)"
        },
        {
          "find": "        seq_emb = seq_emb * self.input_frequency_scale[seq].unsqueeze(-1)",
          "replace": "        seq_emb = seq_emb * self.input_frequency_scale[seq].unsqueeze(-1)\n        seq_emb = seq_emb + self.frequency_projection(self.input_log_frequency[seq].unsqueeze(-1))"
        },
        {
          "find": "    frequency_scale[0] = 0.0\n    with torch.no_grad():\n        model.input_frequency_scale.copy_(torch.as_tensor(\n            frequency_scale, dtype=model.input_frequency_scale.dtype, device=device\n        ))",
          "replace": "    frequency_scale[0] = 0.0\n    log_frequency = np.zeros(itemnum + 1, dtype=np.float64)\n    log_frequency_mean = 0.0\n    log_frequency_std = 1.0\n    if observed_items.any():\n        observed_log_counts = np.log1p(training_counts[observed_items].astype(np.float64))\n        log_frequency_mean = float(observed_log_counts.mean())\n        log_frequency_std = max(float(observed_log_counts.std()), 1e-6)\n        log_frequency[observed_items] = (observed_log_counts - log_frequency_mean) / log_frequency_std\n    with torch.no_grad():\n        model.input_frequency_scale.copy_(torch.as_tensor(\n            frequency_scale, dtype=model.input_frequency_scale.dtype, device=device\n        ))\n        model.input_log_frequency.copy_(torch.as_tensor(\n            log_frequency, dtype=model.input_log_frequency.dtype, device=device\n        ))\n        model.log_frequency_mean.fill_(log_frequency_mean)\n        model.log_frequency_std.fill_(log_frequency_std)"
        },
        {
          "find": "        model.load_state_dict(torch.load(ckpt_path, map_location=_device, weights_only=True))",
          "replace": "        state = torch.load(ckpt_path, map_location=_device, weights_only=True)\\n        required_features = (\"input_log_frequency\", \"log_frequency_mean\", \"log_frequency_std\", \"frequency_projection.weight\")\\n        if any(key not in state for key in required_features):\\n            raise RuntimeError(\"Checkpoint is missing trained frequency features\")\\n        model.load_state_dict(state, strict=True)"
        }
      ]
    }
  ],
  "change_summary": "Apply clipped positions, causal mean readout, mixed ranking/logistic supervision, and checkpointed training-frequency input features across all four independent HSTU category models. Preserve routing, observed histories, seeds, optimizer settings, and training limits."
}
